contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint minSum, uint deposit, uint amount) public payable {
        require(address(this).balance >= deposit);
        c.SetMinSum(minSum);
        c.Deposit{value: deposit}();
        uint balBefore = c.balances(address(this));
        require(balBefore >= minSum);
        require(amount <= balBefore);
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        uint balAfter = c.balances(address(this));
        uint ethAfter = address(c).balance;
        if (reverted) {
            assert(balAfter == balBefore && ethAfter == ethBefore);
        } else {
            assert(balAfter == balBefore - amount && ethAfter == ethBefore - amount);
        }
    }
    receive() external payable {}
}

